module main

// ===========================================================================
// Game data — GENERATED by gen_data.py from the JSON files in assets/data/.
// Do not edit by hand: change the JSON (monsters.json, boss.json, team.json,
// skills.json, particles.json, effects.json, levels.json), then run
// `python gen_data.py`. The JSON files are the source of truth; this V file
// is compiled into the game (the web runtime cannot parse JSON dynamically).
// ===========================================================================

struct ElementData {
	hp     f32
	dmg    f32
	spd    f32
	ranged bool
	range  f32
	tex    string
	proj   string
	skill  string
}

struct EnemyData {
	hp     f32
	dmg    f32
	spd    f32
	ranged bool
	range  f32
	tex    string
	size   [2]f32
	tint   [3]f32
}

struct ParticleData {
	count    int
	size     f32
	speed    f32
	lifetime f32
	texture  string
}

struct SkillData {
	skill_type string
	dmg_mult   f32
	range      f32
	count      int
	effect     string
}

struct EffectData {
	effect_type string
	value       f32
	dmg_mult    f32
	duration    f32
}

struct TeamSlot {
	element string
	level   int
}

struct BossData {
pub mut:
	every       int
	hp_mult     f32
	dmg_mult    f32
	spd         f32
	skill       string
	tex         string
	size_scale  f32
	reward_mult f32
	name        string
	tint        [3]f32
}

struct LevelTuning {
pub mut:
	count       int
	base_reward int
	reward_step int
	waves_min   int
	waves_max   int
	count_base  int
	count_step  int
	mtype_scale int
	level_scale int
}

struct GameData {
pub mut:
	elements   [12]ElementData
	enemies    [20]EnemyData
	particles  [16]ParticleData
	skills     [24]SkillData
	effects    [13]EffectData
	team       [8]TeamSlot
	boss       BossData
	bosses     [10]BossData
	level_mult f32
	levels     LevelTuning
	ready      bool
}

__global (
	g_data GameData
)

fn element_index(e string) int {
	return match e {
		'fire'  { 0 }
		'water' { 1 }
		'earth' { 2 }
		'wind'  { 3 }
		'lightning' { 4 }
		'ice'   { 5 }
		'steam' { 6 }
		'lava'  { 7 }
		'ember' { 8 }
		'mud'   { 9 }
		'mist'  { 10 }
		'dust'  { 11 }
		else    { 5 }
	}
}

fn particle_index(tag string) int {
	return match tag {
		'spawn'      { 0 }
		'merge'      { 1 }
		'kill'       { 2 }
		'levelup'    { 3 }
		'win'        { 4 }
		'boss_death' { 5 }
		'crit'       { 6 }
		'heal'       { 7 }
		'freeze'     { 8 }
		'banner'     { 9 }
		'meteor'     { 10 }
		'freeze_break' { 11 }
		'stun_star'  { 12 }
		'combo'      { 13 }
		'heal_big'   { 14 }
		else         { 15 }
	}
}

