fn element_data(el string) ElementData {
	return g_data.elements[element_index(el)]
}

fn enemy_data(mtype int) EnemyData {
	idx := if mtype < 1 { 0 } else if mtype > 20 { 19 } else { mtype - 1 }
	return g_data.enemies[idx]
}

fn particle_data(tag string) ParticleData {
	return g_data.particles[particle_index(tag)]
}

fn skill_data(s string) SkillData {
	return g_data.skills[skill_index(s)]
}

fn effect_data(e string) EffectData {
	return g_data.effects[effect_index(e)]
}

fn team_slots() []TeamSlot {
	return g_data.team[..]
}

fn boss_count() int {
	return g_data.bosses.len
}

fn boss_index(n int) int {
	mut idx := 0
	if g_data.boss.every > 0 {
		idx = (n / g_data.boss.every) - 1
	}
	if idx < 0 {
		idx = 0
	}
	return idx % 10
}

fn boss_for_level(n int) BossData {
	return g_data.bosses[boss_index(n)]
}

fn level_count() int {
	return g_data.levels.count
}

fn is_boss_level(n int) bool {
	return g_data.boss.every > 0 && n % g_data.boss.every == 0
}
